if (size <= 0) return nullptr;

// Create a priority queue (min-heap) of TreeNodes
auto cmp = [](TreeNode* left, TreeNode* right) { return left->freq > right->freq; };
std::priority_queue<TreeNode*, std::vector<TreeNode*>, decltype(cmp)> minHeap(cmp);

// Create leaf nodes and add them to the min-heap
for (int i = 0; i < size; i++) {
    TreeNode* node = new TreeNode();
    node->data = values[i];
    node->freq = freqs[i];
    node->left = node->right = nullptr;
    minHeap.push(node);
}

// Build the Huffman tree
while (minHeap.size() > 1) {
    // Extract the two nodes with the smallest frequencies
    TreeNode* left = minHeap.top(); minHeap.pop();
    TreeNode* right = minHeap.top(); minHeap.pop();

    // Create a new internal node with these two nodes as children
    TreeNode* newNode = new TreeNode();
    newNode->freq = left->freq + right->freq;
    newNode->data = 0; // Internal nodes don't have meaningful data
    newNode->left = left;
    newNode->right = right;

    // Add the new node back to the min-heap
    minHeap.push(newNode);
}

// The remaining node is the root of the Huffman tree
return minHeap.top();

